// Photo registration of the fetched MCEE facility outlines (osm-ground.json `facilities`, regenerated by fetch/osm.mjs,
// so they stay as fetched): data/photo/evidence/ground-registration.json (todo 9: evidence of the parcel rings in
// data/ground/parcels.json, which the ground stages read; kept applied for the other facility readers) moves original ring vertices by dE/dN metres in
// EPSG:5186 where the NGII 2025 orthophoto shows the outline elsewhere. Each entry names the facility by index and
// l3Code and carries the ring's first vertex (`check`), so a refetch that reorders or reshapes the facilities fails
// loudly instead of moving the wrong polygon. Corrected vertices are estimates (추정).
import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { tmToWgs84, wgs84ToTm } from "../../../src/geo/epsg5186.mjs";

const HERE = path.dirname(fileURLToPath(import.meta.url));
export const GROUND_REGISTRATION = path.join(HERE, "..", "data", "photo", "evidence", "ground-registration.json");

// facilities: osm-ground.json facilities.features ([{ l3Code, rings: [[lon, lat]...] }]); returns a new array.
export function registerFacilities(facilities, registration) {
  const out = facilities.map((f) => ({ ...f, rings: f.rings.map((r) => r.map((p) => [...p])) }));
  for (const c of (registration?.corrections ?? []).filter((x) => x.target === "facility")) {
    const f = out[c.index];
    const ring = f?.rings[c.ring];
    if (!ring || f.l3Code !== c.l3Code || JSON.stringify(facilities[c.index].rings[c.ring][0]) !== JSON.stringify(c.check)) {
      throw new Error(`ground-registration ${c.id}: facility ${c.index} (l3Code ${c.l3Code}) does not match the fetched outline any more`);
    }
    for (const v of c.vertices) {
      if (!ring[v]) throw new Error(`ground-registration ${c.id}: facility ${c.index} ring ${c.ring} has no vertex ${v}`);
      const [E, N] = wgs84ToTm(...facilities[c.index].rings[c.ring][v]);
      ring[v] = tmToWgs84(E + c.dE, N + c.dN);
    }
    f.registration = [...(f.registration ?? []), c.id];
  }
  return out;
}

export const readGroundRegistration = (file = GROUND_REGISTRATION) => JSON.parse(readFileSync(file, "utf8"));
